// Typed bindings for this Worker. `Env` is generated by `wrangler types` into
// worker-configuration.d.ts from wrangler.jsonc, so vars and bindings stay in one place.
// DEV_MAILBOX exists only in the local (top-level) config; named environments omit it.

/**
 * `AI` and `AI_GATEWAY_ID` exist only in named environments (preview, staging, production), so the
 * generated `Env` lacks them; they are optional here and `ai/AiPort.ts` degrades without them.
 */
export type Bindings = Env & {
  AI?: Ai;
  AI_GATEWAY_ID?: string;
  /** App Links / Universal Links (slice 019): set per environment, unset locally. */
  ANDROID_PACKAGE?: string;
  ANDROID_CERT_SHA256?: string;
  APPLE_APP_IDS?: string;
  /**
   * Care notes (D27, slice 030): 32 bytes base64, set with `wrangler secret put CARE_NOTE_KEY`
   * per named environment. Unset locally (a fixed development key stands in); unset in a named
   * environment, care-note writes and reveals answer 503.
   */
  CARE_NOTE_KEY?: string;
  /**
   * Photos (D18, slice 043): 32 bytes base64, `wrangler secret put MEDIA_KEY` per named
   * environment; a fixed development key stands in locally; unset in a named environment, uploads
   * and reads answer 503.
   */
  MEDIA_KEY?: string;
};

/** Who is calling, resolved from the session by auth/middleware.ts. */
export type AuthContext = {
  accountId: string;
  email: string;
  locale: 'ko' | 'en';
  /** Slice 069: the account's own name; null until set (then a role label stands in). */
  displayName: string | null;
  sessionId: string;
  client: 'web' | 'native';
  /** Slice 045 (D35): the session's last step-up confirmation; null until one. */
  reauthedAt: string | null;
};

/** Per-request variables set by middleware. */
export type Variables = {
  correlationId: string;
  auth?: AuthContext;
  /** The presented session was revoked with the wipe directive (D28); set by the middleware. */
  wiped?: boolean;
};

export type AppEnv = { Bindings: Bindings; Variables: Variables };
